def _stable_key(value, prefix, seed):
    key = str(value or '').strip()
    if key:
        return key[:128]
    digest = hashlib.sha1(str(seed or prefix).encode('utf-8')).hexdigest()[:16]
    return f'{prefix}-{digest}'


def backfill_wow_today_cards(apps, schema_editor):
    Snapshot = apps.get_model('botend', 'WowTodaySnapshot')
